async function cardBlob(signId:string,text:string,date:string){
 const s=SIGNS.find(s=>s.id===signId)||SIGNS[6],canvas=document.createElement("canvas");canvas.width=1080;canvas.height=1350;const c=canvas.getContext("2d")!;
 const grad=c.createLinearGradient(0,0,1080,1350);grad.addColorStop(0,"#111024");grad.addColorStop(.55,"#28213e");grad.addColorStop(1,"#111024");c.fillStyle=grad;c.fillRect(0,0,1080,1350);c.strokeStyle="#776783";c.lineWidth=1;c.strokeRect(54,54,972,1242);
 for(let i=0;i<65;i++){c.fillStyle=i%3?"#8d7fa6":"#ddc5a6";c.beginPath();c.arc((i*173+90)%1000+40,(i*217+30)%1250+35,i%4===0?2:1,0,Math.PI*2);c.fill();}
 c.textAlign="center";c.fillStyle="#eee5f5";c.font="24px sans-serif";c.fillText("L Ú M I N A",540,145);c.fillStyle=s.color;c.font="170px Georgia";c.fillText(s.glyph,540,410);c.fillStyle="#fff9ef";c.font="74px Georgia";c.fillText(s.name,540,535);c.font="22px sans-serif";c.fillStyle="#c5b9d0";c.fillText(displayDate(date)+" · "+s.element,540,590);c.strokeStyle="#6e5b80";c.beginPath();c.moveTo(390,650);c.lineTo(690,650);c.stroke();c.font="44px Georgia";c.fillStyle="#f3edf6";let line="",y=770;for(const word of text.slice(0,290).split(" ")){const next=line+(line?" ":"")+word;if(c.measureText(next).width>790){c.fillText(line,540,y);line=word;y+=65;}else line=next;}if(line)c.fillText(line,540,y);c.font="20px sans-serif";c.fillStyle="#bcaec9";c.fillText("Una reflexión recreativa para tu día.",540,1195);c.font="17px sans-serif";c.fillText("Demostración editorial · Mayores de 18 años",540,1232);return await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error("No pudimos crear la tarjeta.")),"image/png"));
}
async function downloadCard(sign:string,text:string,date:string,share=false){const blob=await cardBlob(sign,text,date),file=new File([blob],`LÚMINA-${sign}.png`,{type:"image/png"});if(share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:"Mi pausa astral"});return;}const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);}
