 const p=PRODUCTS.find(p=>p.id===product)!;
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError("");const f=new FormData(e.currentTarget),input={product,name:f.get("name"),birth:f.get("birth"),theme:f.get("theme"),name2:f.get("name2"),birth2:f.get("birth2"),adult:f.get("adult")==="on",terms:f.get("terms")==="on",otherConsent:f.get("otherConsent")==="on",marketing:f.get("marketing")==="on",referral:String(f.get("referral")||"").toUpperCase().trim()||undefined};try{setOrder(await request("orders",input,key.current));setStep(2);window.scrollTo({top:0,behavior:"smooth"});}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
