function Result({id,me}:{id:string;me?:Me|null}){
 const [order,setOrder]=useState<Order|null>(null),[error,setError]=useState(""),[busy,setBusy]=useState(false),[open,setOpen]=useState(0),[saved,setSaved]=useState(""),[notes,setNotes]=useState<Record<number,string>>({});
 async function load(){try{setOrder(await request("orders/"+id));}catch(e){setError((e as Error).message);}}
 useEffect(()=>{load();try{setNotes(JSON.parse(localStorage.getItem("astropy.notes."+id)||"{}"));}catch{}},[id]);
 useEffect(()=>{if(order?.paymentStatus!=="paid"||!["pending","generating"].includes(order.deliveryStatus))return;const t=setInterval(load,3000);return()=>clearInterval(t);},[order?.paymentStatus,order?.deliveryStatus,id]);
 const reveal=useReadingReveal(id,order?.paymentStatus==="paid"&&order?.deliveryStatus==="delivered"&&!!order.result);
 useEffect(()=>{
  if(reveal.show||order?.paymentStatus!=="paid"||order.deliveryStatus!=="delivered")return;
  const modules=Array.from(document.querySelectorAll<HTMLElement>(".reading-module"));if(!modules.length)return;
  let frame=0;
  function update(){
   const line=Math.min(window.innerHeight*.28,180);let current=0;
   modules.forEach((module,i)=>{if(module.getBoundingClientRect().top<=line)current=i;});
   setOpen(current);frame=0;
  }
  function onScroll(){if(!frame)frame=requestAnimationFrame(update);}
  update();window.addEventListener("scroll",onScroll,{passive:true});window.addEventListener("resize",onScroll);
  return()=>{window.removeEventListener("scroll",onScroll);window.removeEventListener("resize",onScroll);if(frame)cancelAnimationFrame(frame);};
 },[id,reveal.show,order?.paymentStatus,order?.deliveryStatus]);
 useEffect(()=>{
  const list=document.querySelector<HTMLElement>(".reading-nav-links"),active=list?.querySelector<HTMLElement>("[aria-current=step]");
  if(!list||!active||list.scrollWidth<=list.clientWidth)return;
  const left=active.offsetLeft-(list.clientWidth-active.offsetWidth)/2;
  list.scrollTo({left:Math.max(0,left),behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth"});
 },[open]);
 async function retry(){setBusy(true);setError("");try{setOrder(await request("orders/"+id+"/retry",{}));}catch(e){setError((e as Error).message);}finally{setBusy(false);}}

 if(!order)return <div className="page-wrap"><a href="/mis-lecturas" className="back-link"><ArrowLeft size={15}/> Mis lecturas</a><ErrorBox error={error}/>{!error&&<p role="status">Preparando tu espacio…</p>}</div>;
 const p=PRODUCTS.find(p=>p.id===order.product)!,s=signFor(order.payload.birth),report=order.result;
 async function share(){try{await downloadCard(s.id,report!.sections[0].prompt,dateKey(),true);event("share_card",order!.product);}catch(e){if((e as Error).name!=="AbortError")setError((e as Error).message);}}
 return <div className="page-wrap result-wrap"><a href="/mis-lecturas" className="back-link"><ArrowLeft size={16}/> Mis lecturas</a><ErrorBox error={error}/>{order.paymentStatus!=="paid"?<div className="empty-state"><Clock size={34}/><h1 className="page-title">Tu lectura, a un <em>paso.</em></h1><p>{p.name} · {money(order.amount)}{order.mode!=="manual_qr"?" · prueba":""}</p><p>{order.paymentStatus==="refunded"?"Este pedido fue reembolsado en el simulador. La descarga está cerrada.":order.paymentStatus==="cancelled"?"La simulación fue cancelada. Podés crear un nuevo pedido.":"Informá tu pago por QR. La lectura se habilita después de verificar el ingreso."}</p>{["pending","failed"].includes(order.paymentStatus)&&<div className="result-qr"><QrCheckout id={order.id} amount={order.amount} test={order.mode!=="manual_qr"}/></div>}</div>:order.deliveryStatus!=="delivered"?<div className="empty-state delivery-preparation">{order.deliveryStatus!=="error"&&<ReadingCeremony phase="preparing"/>}<h1 className="page-title">Tu lectura está <em>en camino.</em></h1><p>{order.deliveryStatus==="error"?"El pago está confirmado. La generación tuvo un error y podés reintentar sin pagar de nuevo.":"Tu pedido ya está aprobado. Actualizá el estado o reintentá si la preparación se interrumpió."}</p>{order.error&&<code>{order.error} · Intentos: {order.attempts}/5</code>}<button disabled={busy} onClick={retry} className="button primary">{busy?"Preparando…":order.deliveryStatus==="error"?"Reintentar entrega":"Actualizar preparación"}<RefreshCw size={17}/></button></div>:reveal.show?<div className="reading-reveal-stage" role="status" aria-label="Pago confirmado. Abriendo tu lectura."><ReadingCeremony phase="reveal" onSkip={reveal.complete}/></div>:report&&<><div className="result-hero"><div className="eyebrow">{p.short.toUpperCase()} · {s.name.toUpperCase()}</div><span className="result-sign">{s.glyph}{order.payload.birth2?" ✧ "+signFor(order.payload.birth2).glyph:""}</span><h1 className="page-title">{report.title}</h1><p>{report.intro}</p><div className="result-actions"><a href={apiUrl(`orders/${id}/pdf`)} className="button primary" onClick={()=>event("pdf_download",p.id)}><Download size={17}/> Descargar PDF</a><button className="button secondary" onClick={share}><Share2 size={17}/> Compartir tarjeta</button></div><small>{report.source==="openai"?"Generado con IA":"Contenido de demostración · Plantilla editorial"} · PDF privado</small></div><div className="reading-layout">
 <aside className="reading-nav" aria-label="Secciones de tu lectura">
  <div className="reading-nav-heading"><span className="eyebrow">TU RECORRIDO</span><h2>Una pausa,<br/><em>a tu ritmo.</em></h2><p>{report.sections.length} momentos para explorar.</p></div>
  <div className="reading-position"><span>Sección {open+1} de {report.sections.length}</span><div aria-hidden="true"><span style={{width:`${(open+1)/report.sections.length*100}%`}}/></div></div>
  <div className="reading-nav-links">{report.sections.map((sec,i)=><button key={i} aria-current={open===i?"step":undefined} onClick={()=>{setOpen(i);document.getElementById("module-"+i)?.scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"instant":"smooth",block:"start"});}} className={open===i?"active":""}><span className="reading-step-number">{String(i+1).padStart(2,"0")}</span><span className="reading-step-title">{sec.title}</span><ArrowRight size={14} aria-hidden="true"/></button>)}</div>
  <div className="reading-nav-note"><BookOpen size={17}/><p>Podés volver a cualquier sección cuando quieras.</p></div>
 </aside>
 <div className="reading-sections">
  {report.sections.map((sec,i)=><ScrollReadingModule key={i} id={"module-"+i}>
   <div className="reading-module-heading"><span className="module-index" aria-hidden="true">{String(i+1).padStart(2,"0")}</span><div><span className="module-number">{p.id==="compatibilidad"?"UN MOMENTO PARA DOS":"UN MOMENTO PARA VOS"}</span><h2 id={`module-${i}-title`}>{sec.title}</h2></div></div>
   <p className="reading-body">{sec.body}</p>
   <div className="reflection"><span className="reflection-icon" aria-hidden="true"><Sparkles size={20}/></span><div><span className="reflection-label">PARA REFLEXIONAR</span><p>{sec.prompt}</p></div></div>
   {p.id==="premium"&&<div className="reading-journal"><label className="journal-label" htmlFor={`journal-${i}`}>Un espacio para tus palabras</label><p id={`journal-hint-${i}`}>Tus notas se guardan en este navegador. Evitá información sensible.</p><textarea id={`journal-${i}`} aria-describedby={`journal-hint-${i}`} maxLength={2000} value={notes[i]||""} onChange={e=>setNotes({...notes,[i]:e.target.value})} onBlur={()=>{try{localStorage.setItem("astropy.notes."+id,JSON.stringify(notes));setSaved("Tus notas se guardaron en este navegador.");}catch{setSaved("No pudimos guardar las notas. Revisá el almacenamiento de tu navegador.");}}} placeholder="Escribí si te dan ganas…" rows={3}/></div>}
  </ScrollReadingModule>)}
  {saved&&<p className="reading-save-status" role="status"><Check size={15}/>{saved}</p>}
  <div className="reading-closing"><span className="reading-closing-icon" aria-hidden="true"><Star size={23}/></span><h2>Lo que sigue, empieza en vos.</h2><p>{report.closing}</p><a className="text-link" href="/#horoscopo">Volver a la pausa de hoy <ArrowRight size={16}/></a></div>
 </div>
</div></>}</div>;
}
function Admin(){
 const [d,setD]=useState<any>(null),[error,setError]=useState(""),[busy,setBusy]=useState(false),[notice,setNotice]=useState("");const expenseKey=useRef("");
 async function load(){try{setD(await request("admin/dashboard"));}catch(e){setError((e as Error).message);}}
 useEffect(()=>{load();expenseKey.current=newRequestKey();},[]);
 async function expense(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form);setBusy(true);setError("");try{await request("admin/expenses",{date:f.get("date"),category:f.get("category"),amount:Number(f.get("amount")),note:String(f.get("note")||"")},expenseKey.current);expenseKey.current=newRequestKey();form.reset();setNotice("Gasto de prueba registrado.");await load();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function refund(id:string){setBusy(true);try{await request("admin/refund/"+id,{});setNotice("Reembolso simulado registrado. No se movió dinero.");await load();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 const kpis=d?[{label:"Ventas de hoy",value:String(d.todaySales),note:"Pedidos con pago confirmado"},{label:"Facturación de hoy",value:money(d.todayRevenue),note:"Importe final · PYG"},{label:"Facturación neta del mes",value:money(d.monthRevenue),note:"Cobros menos reembolsos"},{label:"Resultado operativo estimado",value:money(d.netBeforeTax),note:"Con reserva IVA · antes de IRE/IRP"}]:[];
 return <div className="admin-wrap"><div className="section-top"><div><div className="eyebrow">LÚMINA / GESTIÓN</div><h1 className="page-title">Una mirada al <em>negocio.</em></h1><p className="page-subtitle">Gestioná tus QR, revisá avisos de pago y seguí el resultado. Los pedidos de prueba no representan ventas reales.</p></div><div className="admin-actions"><button className="button secondary" onClick={load}><RefreshCw size={15}/> Actualizar</button><a className="button primary" href={apiUrl("admin/export")}><Download size={15}/> Exportar CSV</a></div></div><ErrorBox error={error}/>{!d&&!error&&<p role="status">Cargando el panel…</p>}{d&&<><QrAdmin/><div className="kpi-grid">{kpis.map(k=><div className="kpi" key={k.label}><span>{k.label}</span><strong>{k.value}</strong><small>{k.note}</small></div>)}</div><div className="admin-main"><section className="admin-panel sales-panel"><div className="panel-heading"><h3>Facturación registrada</h3><span>Últimos 14 días</span></div><div className="bar-chart" role="img" aria-label="Facturación diaria registrada de los últimos catorce días">{d.series.map((x:any)=><div className="bar-col" key={x.date} title={x.date+": "+money(x.amount)}><span>{x.amount?money(x.amount):""}</span><div style={{height:Math.max(x.amount/Math.max(...d.series.map((s:any)=>s.amount),1)*150,2)}}/><small>{x.date.slice(-2)}</small></div>)}</div>{!d.monthRevenue&&<p className="quiet-note">Los datos aparecerán después de completar una compra de prueba.</p>}</section><section className="admin-panel cost-panel"><div className="panel-heading"><h3>Del ingreso al resultado</h3><span>{d.month}</span></div>{([["Facturación cobrada",d.monthGross],["Reversas registradas",-d.refunds],["Comisiones registradas",-d.fees],["Costo IA registrado",-d.aiCost],["Publicidad registrada",-d.adSpend],["Otros gastos registrados",-d.fixedCosts],["Reserva IVA (hipótesis)",-d.vatReserve]]as [string,number][]).map(([label,v])=><div className="cost-line" key={label}><span>{label}</span><strong>{money(v)}</strong></div>)}<div className="cost-line total"><span>Resultado operativo estimado</span><strong>{money(d.netBeforeTax)}</strong></div><small>Comisión e IVA son supuestos. Sin créditos fiscales, impuestos a la renta ni valor del trabajo del propietario. Sin gastos registrados se sobreestima el resultado.</small></section></div><div className="mini-kpis">{([["Pagos pendientes",d.pending],["Pedidos entregados",d.delivered],["Clientes recurrentes",d.recurringCustomers],["Referidos pagos (prueba)",d.referrals],["Descuentos del mes",money(d.discounts)],["CAC mixto del mes",d.cac===null?"Sin clientes":money(d.cac)]]as [string,string|number][]).map(([label,v])=><div key={label}><span>{label}</span><strong>{v}</strong></div>)}</div><div className="admin-main"><section className="admin-panel"><h3>Productos del mes</h3>{d.products.map((p:any)=><div className="product-stat" key={p.id}><span>{p.name}<small>{p.count} pedidos</small></span><strong>{money(p.revenue)}</strong></div>)}<p className="quiet-note">Recurrentes: historial total. CAC: publicidad del mes / nuevos clientes del mes, mezcla canales y requiere atribución antes de decidir.</p></section><section className="admin-panel"><h3>Registrar un gasto de prueba</h3><form onSubmit={expense} className="expense-form" onChange={()=>{expenseKey.current=newRequestKey();}}><div className="form-row"><label>Fecha<input type="date" name="date" defaultValue={dateKey()} required/></label><label>Categoría<select name="category"><option value="publicidad">Publicidad</option><option value="hosting">Hosting</option><option value="herramientas">Herramientas</option><option value="otros">Otros</option></select></label></div><div className="form-row"><label>Importe PYG<input type="number" min={1} max={20000000} step={1} name="amount" required placeholder="Ej. 12000"/></label><label>Nota<input name="note" maxLength={120} placeholder="Ej. Experimento A"/></label></div><button disabled={busy} className="button secondary"><Plus size={15}/> Registrar gasto</button></form></section></div><section className="admin-panel"><div className="panel-heading"><h3>Pedidos recientes</h3><span>Hasta 1.000 pedidos · CSV hasta 10.000</span></div><div className="table-scroll"><table><thead><tr><th>Pedido</th><th>Producto</th><th>Importe PYG</th><th>Pago</th><th>Entrega</th><th>Acción</th></tr></thead><tbody>{d.orders.map((o:Order)=><tr key={o.id}><td>{o.id.slice(0,8)}</td><td>{PRODUCTS.find(p=>p.id===o.product)?.short}</td><td>{money(o.amount)}</td><td><span className={o.paymentStatus==="paid"?"status delivered":"status"}>{({paid:"Aprobado",pending:"Pendiente",failed:"Rechazado",cancelled:"Cancelado",refunded:"Reembolsado"}as any)[o.paymentStatus]}</span></td><td>{({delivered:"Entregado",pending:"Pendiente",error:"Error",generating:"Generando"}as any)[o.deliveryStatus]}</td><td>{o.paymentStatus==="paid"&&o.mode!=="manual_qr"&&<button className="table-button" disabled={busy} onClick={()=>refund(o.id)}>Reembolsar (prueba)</button>}</td></tr>)}</tbody></table>{!d.orders.length&&<p className="quiet-note">Todavía no hay pedidos.</p>}</div></section><section className="admin-panel"><h3>Entregas que requieren atención</h3>{d.errors.length?d.errors.map((o:Order)=><div className="error-row" key={o.id}><AlertCircle size={17}/><span>{o.id.slice(0,8)} · {o.error} · {o.attempts}/5 intentos</span><a href={"/resultado/"+o.id} className="text-link">Revisar <ArrowUpRight size={14}/></a></div>):<p className="quiet-note">No hay errores de entrega registrados.</p>}</section><p className="quiet-note">Panel del propietario en piloto privado. El rol de producción, atribución por canal, conciliación y facturación tributaria están pendientes.</p></>}{notice&&<p className="notice" role="status">{notice}</p>}</div>;
}
function LegalPage({id}:{id:string}){const doc=LEGAL[id];if(!doc)return <div className="page-wrap"><h1>Documento no encontrado.</h1></div>;return <article className="legal-page page-wrap"><a className="back-link" href="/"><ArrowLeft size={15}/> Volver al inicio</a><div className="eyebrow">CLARIDAD Y CONFIANZA</div><h1 className="page-title">{doc.title}</h1><p className="legal-banner">Borrador del piloto privado. Sujeto a revisión profesional antes del uso comercial.</p>{doc.sections.map(s=><section key={s.title}><h2>{s.title}</h2><p>{s.body}</p></section>)}</article>;}
function Home(){
 const [sign,setSign]=useState("libra"),[daily,setDaily]=useState<Daily[]>([]),[date,setDate]=useState(dateKey()),[error,setError]=useState(""),[sharing,setSharing]=useState(false),[loading,setLoading]=useState(true),[preview,setPreview]=useState(0);
 const sampleMotion=useInViewMotion<HTMLElement>(),dailyMotion=useInViewMotion<HTMLElement>();
 useEffect(()=>{setSign(localStorage.getItem("astropy.sign")||"libra");load();},[]);
 async function load(){setLoading(true);setError("");try{const d=await request("daily");setDaily(d.items);setDate(d.date);}catch(e){setError((e as Error).message);}finally{setLoading(false);}}
 const current=SIGNS.find(s=>s.id===sign)||SIGNS[6],reading=daily.find(d=>d.sign===sign),icons=[Heart,Briefcase,Leaf,Sparkles];
 async function share(download=false){if(!reading)return;setSharing(true);try{await downloadCard(sign,reading.title,date,!download);event("share_card");}catch(e){if((e as Error).name!=="AbortError")setError((e as Error).message);}finally{setSharing(false);}}
 const excerpts=[
  {title:"Dos universos, una conexión",body:"Cada persona tiene su manera de sentir y de acercarse. Exploramos los dos perfiles zodiacales como una invitación a conocerse, más allá de las primeras impresiones.",question:"¿Qué te gustaría que la otra persona entendiera mejor de vos?"},
  {title:"Lo que los acerca",body:"Sus afinidades y diferencias son un punto de partida para conversar. Una mirada simbólica sobre lo que disfrutan juntos y esas pequeñas cosas que cada uno hace a su manera.",question:"¿Qué disfrutan juntos sin necesidad de hacerlo igual?"},
  {title:"Una pregunta para dos",body:"Regálense diez minutos sin apuro. Cada persona comparte algo que agradece y una idea para esta semana. El informe incluye preguntas y una práctica para llevar a su día a día.",question:"¿Qué pequeño acuerdo les gustaría probar esta semana?"},
 ];
 return <>
  <section className="hero sales-hero couples-hero">
   <div className="hero-copy">
    <div className="eyebrow"><span className="small-line"/> UNA EXPERIENCIA PARA COMPARTIR</div>
    <h1>Dos universos.<br/>Una conexión.<br/><em>Denle luz.</em><span className="headline-spark" aria-hidden="true">✳</span></h1>
    <p>Sus signos, sus diferencias, eso que los acerca. Una lectura con sus nombres para conocerse de otra manera y abrir una conversación especial.</p>
    <div className="hero-actions">
     <a href="/experiencia?producto=compatibilidad" className="button primary purchase-cta" onClick={()=>event("product_view","compatibilidad")}><span>Explorar nuestra conexión</span><ArrowUpRight size={20}/></a>
     <span className="hero-price">₲29.000<small>una lectura para dos · pago único</small></span>
    </div>
    <a className="hero-free-link" href="#muestra">Primero quiero ver qué recibimos <ArrowRight size={16}/></a>
    <div className="hero-footnote"><span><BookOpen size={15}/> Dos perfiles + PDF privado</span><span><QrCodeIcon/> Pago con QR</span></div>
   </div>
   <div className="hero-universe">
    <ZodiacWheel/>
    <div className="hero-report">
     <div className="report-topline"><span>LÚMINA ✳</span><small>MUESTRA DE LECTURA</small></div>
     <div className="report-moon report-pair" aria-hidden="true"><span>♎︎</span><small>✧</small><span>♌︎</span></div>
     <span className="report-kicker">ENTRE DOS ESTRELLAS</span>
     <h3>Lo que los hace<br/><em>conectar.</em></h3>
     <p>Dos formas de ser.<br/>Algo nuevo para compartir.</p>
     <div className="report-divider"/>
     <span className="report-chip">01 / Sus dos universos</span><span className="report-chip">02 / Un punto de encuentro</span>
     <div className="report-footer">SU HISTORIA · SU RITMO <span>✧</span></div>
    </div>
    <div className="hero-price-bubble"><Heart size={17}/><span>Una pausa para dos.<br/><strong>Una nueva forma de mirarse.</strong></span></div>
   </div>
   <a className="scroll-cue" href="#experiencias"><span>ENCONTRÁ TU LECTURA</span><ChevronDown size={16}/></a>
  </section>
  <div className="principles"><span>✳ HECHO PARA COMPARTIR</span><span>✧</span><span>PRECIOS EN GUARANÍES</span><span>✧</span><span>PDF PARA GUARDAR</span><span>✧</span><span>SIN SUSCRIPCIÓN</span></div>
  <section id="experiencias" className="experiences section">
   <div className="section-top"><div><div className="eyebrow">ELEGÍ TU PRÓXIMO DESCUBRIMIENTO</div><h2>Una lectura.<br/><em>Muchas formas de conectar.</em></h2><p>Con vos, con alguien especial, con una pregunta que merece espacio.</p></div><span className="small-label">PAGO ÚNICO · SIN SUSCRIPCIÓN</span></div>
   <div className="product-grid">{PRODUCTS.map((p,i)=>{
    const featured=p.id==="compatibilidad";
    return <article className={featured?"product-card featured couple-offer":"product-card"} key={p.id} data-product={p.id}>
     <span className={featured?"product-tag":"product-tag muted-tag"}>{featured?"PARA COMPARTIR ENTRE DOS":p.id==="lectura"?"UN MOMENTO PARA VOS":"EXPERIENCIA AMPLIADA · PROTOTIPO"}</span>
     <div className="product-art"><Constellation index={i*4+2}/>{featured?<><span className="paired-glyph">♎︎</span><span className="connection">✧</span><span className="paired-glyph second">♌︎</span></>:<span>{p.id==="lectura"?"☾":"✳"}</span>}</div>
     <span className="product-number">0{i+1}</span><h3>{p.name}</h3><p>{p.description}</p>
     <ul>{p.features.map(f=><li key={f}><Check size={15}/>{f}</li>)}</ul>
     <div className="price">{money(p.price)}<span> / pago único</span></div>
     <a className={featured?"button primary purchase-cta":"button secondary"} href={`/experiencia?producto=${p.id}`} onClick={()=>event("product_view",p.id)}><span>{featured?"Explorar nuestra conexión":p.id==="lectura"?"Quiero mi lectura":"Ver experiencia ampliada"}</span><ArrowUpRight size={17}/></a>
    </article>;
   })}</div>
   <p className="quiet-note preview-disclosure">Vista privada: los informes siguen siendo demostraciones editoriales y los cobros están en prueba.</p>
  </section>
  <section id="muestra" ref={sampleMotion.ref} data-motion={sampleMotion.active?"active":"idle"} className="sample-section section motion-region">
   <div className="sample-intro">
    <div className="eyebrow">ANTES DE ELEGIR, MIREN POR DENTRO</div><h2>Algo más que<br/><em>sus dos signos.</em></h2>
    <p>Así se siente Entre dos estrellas: dos perfiles, afinidades y preguntas para abrir una conversación que sea solo de ustedes.</p>
    <div className="sample-tabs" role="tablist" aria-label="Fragmentos del informe de pareja">{excerpts.map((x,i)=><button key={x.title} role="tab" aria-selected={preview===i} aria-controls="sample-content" id={`sample-tab-${i}`} onClick={()=>setPreview(i)}><span>0{i+1}</span>{x.title}<ArrowUpRight size={16}/></button>)}</div>
    <a className="button primary purchase-cta sample-buy" href="/experiencia?producto=compatibilidad" onClick={()=>event("product_view","compatibilidad")}><span>Quiero nuestra lectura · ₲29.000</span><ArrowRight size={18}/></a>
    <span className="sample-purchase-note">Una experiencia para dos · PDF para guardar</span>
   </div>
   <div className="sample-stage">
    <span className="sample-spark sample-spark-one" aria-hidden="true">✧</span><span className="sample-spark sample-spark-two" aria-hidden="true">✦</span>
    <article className="sample-paper" id="sample-content" role="tabpanel" aria-labelledby={`sample-tab-${preview}`}>
     <div className="paper-brand"><span>LÚMINA ✳</span><small>FRAGMENTO ILUSTRATIVO</small></div>
     <span className="paper-symbol paper-pair" aria-hidden="true"><span>♎︎</span><small>✧</small><span>♌︎</span></span>
     <span className="eyebrow">LECTURA PARA DOS / 0{preview+1}</span>
     <div key={preview} className="sample-copy"><h3>{excerpts[preview].title}</h3><p>{excerpts[preview].body}</p><blockquote>{excerpts[preview].question}</blockquote></div>
     <div className="paper-bottom"><span>Una experiencia recreativa para reflexionar.</span><span>0{preview+1} — LÚMINA</span></div>
    </article>
   </div>
  </section>
  <section className="how-section section">
   <div className="how-intro"><div className="eyebrow">DE SU CURIOSIDAD A SU LECTURA</div><h2>Su momento,<br/>en tres <em>pasos.</em></h2><p>Todo desde tu celular. El importe y el titular siempre visibles antes de pagar.</p><span className="decorative-spark" aria-hidden="true">✳</span></div>
   <div className="steps">{[{title:"Hacela personal",body:"Elegí tu experiencia y completá los nombres o alias y fechas de nacimiento de quienes participan."},{title:"Pagá con QR",body:"Escaneá el código e informá la referencia. Verificamos el ingreso antes de preparar la lectura."},{title:"Abrí su nuevo universo",body:"Después de confirmar el pago, prepararemos su lectura. La encontrás en Mis lecturas, con su PDF para descargar."}].map((s,i)=><div className="step" key={s.title}><span>0{i+1}</span><div><h3>{s.title}</h3><p>{s.body}</p></div></div>)}</div>
  </section>
  <section id="horoscopo" ref={dailyMotion.ref} data-motion={dailyMotion.active?"active":"idle"} className="daily-section section motion-region">
   <div className="section-top"><div><div className="eyebrow">TU PRIMER DESTELLO ES GRATIS</div><h2>Un poquito de cielo.<br/><em>Todos los días.</em></h2><p>Elegí tu signo y descubrí una reflexión para hoy.</p></div><div className="date-chip"><span className="live-dot"/>{displayDate(date)}<small>Hora de Asunción</small></div></div>
   <div className="sign-grid" role="group" aria-label="Elegí tu signo">{SIGNS.map((s,i)=><button key={s.id} className={sign===s.id?"sign-button active":"sign-button"} style={{"--sign-delay":`${i*-.37}s`} as React.CSSProperties} onClick={()=>{setSign(s.id);localStorage.setItem("astropy.sign",s.id);}} aria-pressed={sign===s.id}><span className="sign-glyph" style={{color:s.color}}>{s.glyph}</span><span>{s.name}</span></button>)}</div>
   <ErrorBox error={error}/>{error&&<button className="text-link" onClick={load}><RefreshCw size={16}/> Reintentar</button>}
   <div className="daily-card" style={{"--sign-color":current.color} as React.CSSProperties}>
    <aside className="daily-sign animated-daily-sign" key={sign}>
     <div className="eyebrow">EL CIELO COMO INSPIRACIÓN</div>
     <div className="daily-sign-art" aria-hidden="true"><span className="daily-sign-orbit"/><span className="daily-sign-spark">✧</span><span className="large-glyph">{current.glyph}</span></div>
     <h3>{current.name}</h3><span>{current.dates}</span><div className="element-pill">{current.element} <span>✧</span> {current.trait}</div>
     <Constellation index={SIGNS.findIndex(s=>s.id===sign)} className="sign-constellation"/>
    </aside>
    <div className="daily-content"><div className="card-label">TU HORÓSCOPO DE HOY <span>GRATIS</span></div>{loading?<div className="loading-copy" role="status">Preparando tu pausa…</div>:reading?<>
     <h3>{reading.title}</h3><div className="daily-areas">{reading.sections.map((s,i)=>{const Icon=icons[i];return <div key={s.title}><h4><Icon size={16}/>{s.title}</h4><p>{s.body}</p></div>;})}</div>
     <div className="daily-bottom"><span>Reflexión recreativa · Demo editorial</span><div><button disabled={sharing} onClick={()=>share(true)} className="icon-link" aria-label="Descargar tarjeta PNG"><Download size={17}/></button><button disabled={sharing} onClick={()=>share()} className="share-button"><Share2 size={16}/> Compartí tu tarjeta</button></div></div>
    </>:<p>No se pudo cargar el contenido de hoy.</p>}</div>
   </div>
   <div className="daily-upsell couples-upsell">
    <span className="upsell-star" aria-hidden="true">✳</span><div className="upsell-copy"><strong>Tu signo es solo el comienzo.</strong><span>¿Y si ahora descubren su conexión?</span></div>
    <a href="/experiencia?producto=compatibilidad" className="button primary purchase-cta" onClick={()=>event("product_view","compatibilidad")}><span>Quiero nuestra lectura · ₲29.000</span><ArrowRight size={19}/></a>
   </div>
  </section>
  <section className="faq section">
   <div><div className="eyebrow">ELEGÍ CON TRANQUILIDAD</div><h2>Tu curiosidad.<br/><em>Las cosas claras.</em></h2></div>
   <div className="faq-list">{[{q:"¿Qué recibimos con Entre dos estrellas?",a:"Un informe recreativo con los dos perfiles zodiacales, afinidades y diferencias simbólicas, y preguntas para conversar. Podés leerlo desde tu cuenta y descargarlo en PDF. La vista privada actual utiliza contenido editorial de demostración."},{q:"¿Es un pago único?",a:"Sí. Los ₲29.000 de Entre dos estrellas corresponden al informe para las dos personas. No hay suscripción ni renovación automática. También podés elegir la lectura personal de ₲19.000."},{q:"¿Cómo funciona el pago con QR?",a:"Se muestra un QR vigente por el importe exacto, con el nombre real de quien recibe. Informás el nombre del remitente y la referencia; verificamos el ingreso antes de habilitar la entrega. Cargar un aviso no confirma el pago. En esta vista privada se prueba el circuito sin realizar pagos reales."},{q:"¿Cuándo recibo el informe?",a:"Después de verificar manualmente el pago y preparar el contenido. Podés consultar el estado desde Mis lecturas. Si ya informaste tu operación, no vuelvas a pagar. El horario de atención y el plazo comercial deben definirse antes de abrir las ventas."},{q:"¿Esto predice nuestro futuro o calcula una carta natal?",a:"Es una experiencia simbólica para reflexionar. No predice hechos ni calcula posiciones planetarias, ascendente o carta natal. Tampoco determina la personalidad o el futuro de una relación."},{q:"¿Puedo ver un ejemplo antes de elegir?",a:"Sí. La sección «Miren por dentro» muestra fragmentos ilustrativos del estilo del informe de pareja. Tu historial y tu PDF requieren tu sesión."}].map(s=><details key={s.q}><summary>{s.q}<Plus size={17}/></summary><p>{s.a}</p></details>)}</div>
  </section>
  <section className="closing-cta"><span className="closing-spark" aria-hidden="true">✳</span><div className="eyebrow">DOS NOMBRES. UNA NUEVA CONVERSACIÓN.</div><h2>Hay algo especial<br/><em>entre sus estrellas.</em></h2><a href="/experiencia?producto=compatibilidad" className="button primary purchase-cta" onClick={()=>event("product_view","compatibilidad")}><span>Explorar nuestra conexión · ₲29.000</span><ArrowUpRight size={19}/></a><p>Una lectura para dos · Pago único · PDF privado</p></section>
  <div className="mobile-buy-bar"><div><span>Entre dos estrellas · para dos</span><strong>₲29.000 <small>/ pago único</small></strong></div><a className="button primary purchase-cta" href="/experiencia?producto=compatibilidad" onClick={()=>event("product_view","compatibilidad")}><span>La queremos</span><ArrowUpRight size={17}/></a></div>
 </>;
}
function QrCodeIcon(){return <svg width="15" height="15" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M2 2h6v6H2zM12 2h6v6h-6zM2 12h6v6H2z" stroke="currentColor" strokeWidth="1.5"/><path d="M12 12h3v3h3v3h-6z" fill="currentColor"/></svg>;}
